def repair(source, action):
    lines = source.splitlines()
    if action == 0 and not lines[0].endswith(":"):
        lines[0] += ":"
    elif action == 1:
        lines[-1] += ")"
    elif action == 2:
        lines[-1] += '"'
    elif action == 3:
        lines[-1] = "    " + lines[-1].lstrip()
    return "\n".join(lines) + "\n"

